// TypeScript Version: 4.1

/**
* Interface describing `dtrapezoid`.
*/
interface Routine {
	/**
	* Computes the integral of a double-precision floating-point strided array using the trapezoidal rule.
	*
	* ## Notes
	*
	* -   If `N <= 1`, the function returns `0.0`.
	* -   The function computes an approximation of the integral using the trapezoidal rule whose accuracy depends on the sample point spacing and the smoothness of the underlying function.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @returns integral approximation
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
	* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
	*
	* var out = dtrapezoid( x.length, x, 1, y, 1 );
	* // returns 9.5
	*/
	( N: number, x: Float64Array, strideX: number, y: Float64Array, strideY: number ): number;

	/**
	* Computes the integral of a double-precision floating-point strided array using the trapezoidal rule and alternative indexing semantics.
	*
	* ## Notes
	*
	* -   If `N <= 1`, the function returns `0.0`.
	* -   The function computes an approximation of the integral using the trapezoidal rule whose accuracy depends on the sample point spacing and the smoothness of the underlying function.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param offsetY - starting index for `y`
	* @returns integral approximation
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
	* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
	*
	* var out = dtrapezoid.ndarray( x.length, x, 1, 0, y, 1, 0 );
	* // returns 9.5
	*/
	ndarray( N: number, x: Float64Array, strideX: number, offsetX: number, y: Float64Array, strideY: number, offsetY: number ): number;
}

/**
* Computes the integral of a double-precision floating-point strided array using the trapezoidal rule.
*
* @param N - number of indexed elements
* @param x - first input array
* @param strideX - stride length for `x`
* @param y - second input array
* @param strideY - stride length for `y`
* @returns integral approximation
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
*
* var out = dtrapezoid( x.length, x, 1, y, 1 );
* // returns 9.5
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
*
* var out = dtrapezoid.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns 9.5
*/
declare var dtrapezoid: Routine;


// EXPORTS //

export = dtrapezoid;
